{
	"name": "opencode-drawer-statusline",
	"version": "1.6.0",
	"description": "A compact prompt status line for OpenCode — directory, worktree, branch, session status, and OpenCode version under every prompt.",
	"type": "module",
	"license": "MIT",
	"repository": {
		"type": "git",
		"url": "git+https://github.com/fredcamaral/drawers.git",
		"directory": "packages/opencode/statusline"
	},
	"keywords": [
		"opencode",
		"opencode-plugin",
		"statusline",
		"tui"
	],
	"exports": {
		".": "./dist/index.js",
		"./tui": "./dist/tui.js"
	},
	"files": [
		"dist",
		"README.md"
	],
	"publishConfig": {
		"access": "public"
	},
	"dependencies": {
		"@opencode-ai/plugin": "1.16.2"
	},
	"peerDependencies": {
		"@opentui/solid": "0.3.2",
		"solid-js": "1.9.12"
	},
	"peerDependenciesMeta": {
		"@opentui/solid": {
			"optional": true
		},
		"solid-js": {
			"optional": true
		}
	}
}
